package com.bank.chain;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CycleDetectDemo {

    private static final Logger log = Logger.getLogger(CycleDetectDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ChainCycleDetector detector = new ChainCycleDetector();

        // Clean chain: T1 → T2 → T3 → T4 → null
        TxnNode t1 = new TxnNode("T1");
        TxnNode t2 = new TxnNode("T2");
        TxnNode t3 = new TxnNode("T3");
        TxnNode t4 = new TxnNode("T4");
        t1.next = t2; t2.next = t3; t3.next = t4;

        TxnNode cleanEntry = detector.cycleStart(t1);
        log.info(() -> "Clean chain cycle entry: " + (cleanEntry == null ? "none" : cleanEntry.id));

        // Corrupted chain: T4 loops back to T2
        t4.next = t2;
        TxnNode loopEntry = detector.cycleStart(t1);
        log.info(() -> "Corrupted chain cycle entry: " + (loopEntry == null ? "none" : loopEntry.id));
    }
}

