class TxnNode {
    final String id;
    TxnNode next;
    TxnNode(String id) { this.id = id; }
}

// ─── Would be in service/ChainCycleDetector.java in a real project ───
class ChainCycleDetector {

    private static final Logger log = Logger.getLogger(ChainCycleDetector.class.getName());

    // Returns the node where the cycle starts, or null if there is no cycle.
    TxnNode cycleStart(TxnNode head) {
        TxnNode slow = head, fast = head;

        // Phase 1: detect a meeting inside the loop.
        while (fast != null && fast.next != null) {
            slow = slow.next;            // +1
            fast = fast.next.next;       // +2
            if (slow == fast) {
                log.fine(() -> "  pointers met inside a cycle");
                // Phase 2: find the entry. Reset one pointer to head.
                TxnNode p = head;
                while (p != slow) {
                    p = p.next;
                    slow = slow.next;
                }
                return p;                // cycle entry node
            }
        }
        return null;                     // fast hit end → no cycle
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
